// =====================================================================
// ⚙️ CONFIGURACIÓN — edita SOLO este bloque
// =====================================================================
const CONFIG = {
  // Mismo valor que "Secreto del Webhook" en la app (Redes Sociales). Vacío = no se valida.
  WEBHOOK_SECRET: '',
  // true = no publica nada: solo registra lo que haría (para probar el flujo)
  DRY_RUN: false,

  // Redes activas
  YOUTUBE: true,
  INSTAGRAM: true,
  TIKTOK: true,

  // YouTube (la cuenta se elige en la credencial del nodo "YouTube: subir Short")
  YOUTUBE_CATEGORY_ID: '25',   // 25 = Noticias y política
  YOUTUBE_REGION: 'EC',

  // Instagram (API de Instagram con inicio de sesión de Facebook; cuenta profesional vinculada a una página)
  INSTAGRAM_USER_ID: '',       // ID de la cuenta de Instagram (empieza con 1784...)
  INSTAGRAM_TOKEN: '',         // token con permisos instagram_basic + instagram_content_publish
  GRAPH_VERSION: 'v26.0',
  INSTAGRAM_REELS: true,       // publica el video como Reel
  INSTAGRAM_STORIES: true,     // además, publica el video como historia

  // Página de Facebook (Reels). Usa el mismo INSTAGRAM_TOKEN: debe incluir pages_manage_posts
  FACEBOOK: false,
  FACEBOOK_STORIES: true,   // además, publica el video como historia de la página
  FACEBOOK_PAGE_ID: '1500702656452606',   // página Radar 593

  // TikTok (Content Posting API)
  TIKTOK_CLIENT_KEY: '',
  TIKTOK_CLIENT_SECRET: '',
  TIKTOK_REFRESH_TOKEN: '',    // solo la primera vez: después se renueva y guarda solo
  TIKTOK_MODE: 'inbox',        // 'inbox' = llega a tus borradores de TikTok (no requiere app auditada)
                               // 'direct' = publica directo (requiere scope video.publish)
  TIKTOK_PRIVACY: 'SELF_ONLY', // en 'direct': apps sin auditar solo pueden SELF_ONLY

  // App Viral Shorts: n8n le avisa cada publicación y le envía las métricas para que aprenda
  APP_URL: 'http://localhost:3000',
  METRICS: true,               // recolecta vistas/likes cada 6 horas (YouTube, Instagram, Facebook)

  // Telegram: te envía el texto de cada video para pegarlo en TikTok
  TELEGRAM_BOT_TOKEN: '',      // ← PEGA AQUÍ el token que te dio @BotFather
  TELEGRAM_CHAT_ID: '',        // vacío = se detecta solo cuando pulsas "Iniciar" en tu bot
};
// =====================================================================

const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};
// Ejecución interna (programador de métricas): no viene del webhook
const isInternal = !item.json.headers && !item.json.body;
const event = isInternal ? 'metrics.collect' : String(body.event || 'reel.publish');
const authorized = isInternal ? CONFIG.METRICS !== false : !CONFIG.WEBHOOK_SECRET || headers['x-webhook-secret'] === CONFIG.WEBHOOK_SECRET;

// Video binario (la app lo envía en el campo "data")
const keys = Object.keys(item.binary || {});
const videoKey = keys.includes('data') ? 'data' : keys[0];
const binary = {};
let videoBytes = 0;
if (videoKey) {
  binary.video = item.binary[videoKey];
  const buf = await this.helpers.getBinaryDataBuffer(0, videoKey);
  videoBytes = buf.length;
}

let hashtags = [];
try { hashtags = JSON.parse(body.hashtags || '[]'); } catch { hashtags = String(body.hashtagsText || '').split(/[\s,]+/).filter(Boolean); }
hashtags = hashtags.map(h => String(h).trim()).filter(Boolean).map(h => (h.startsWith('#') ? h : '#' + h));
if (!hashtags.some(h => h.toLowerCase() === '#shorts')) hashtags.push('#Shorts');

const title = String(body.title || 'Nuevo video').trim();
const description = String(body.description || '').trim();
const cut = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);

const ytTitle = cut(title.includes('#Shorts') ? title : `${title} #Shorts`, 100);
const ytDescription = cut(`${description}\n\n${hashtags.join(' ')}`.trim(), 4900);
const caption = cut(`${title}\n\n${description}\n\n${hashtags.slice(0, 30).join(' ')}`.trim(), 2200);

const scheduledAt = String(body.scheduledAt || '').trim();
const scheduledMs = scheduledAt ? Date.parse(scheduledAt) : NaN;
const isScheduled = Number.isFinite(scheduledMs) && scheduledMs > Date.now() + 60000;
const isTest = event === 'reel.publish.test';
const dryRun = CONFIG.DRY_RUN || isTest;

// Facebook exige token de PÁGINA: si el token pegado es de usuario, se obtiene el de la página automáticamente
let facebookToken = CONFIG.INSTAGRAM_TOKEN;
if (CONFIG.FACEBOOK && CONFIG.FACEBOOK_PAGE_ID && CONFIG.INSTAGRAM_TOKEN && (event === 'metrics.collect' || (!dryRun && Boolean(videoKey)))) {
  try {
    const pg = await this.helpers.httpRequest({ method: 'GET', url: `https://graph.facebook.com/${CONFIG.GRAPH_VERSION}/${CONFIG.FACEBOOK_PAGE_ID}`, qs: { fields: 'access_token', access_token: CONFIG.INSTAGRAM_TOKEN }, json: true, timeout: 15000 });
    if (pg && pg.access_token) facebookToken = pg.access_token;
  } catch (e) { /* ya es token de página o no tiene acceso: se usa tal cual */ }
}

return [{
  json: {
    authorized,
    event,
    isDelete: event === 'reel.delete',
    isTest,
    reelId: body.reelId || '',
    scriptId: body.scriptId || '',
    isMetrics: event === 'metrics.collect',
    title, ytTitle, ytDescription, caption,
    tags: hashtags.map(h => h.replace(/^#/, '')).join(','),
    privacyStatus: ['public', 'unlisted', 'private'].includes(body.privacyStatus) ? body.privacyStatus : 'public',
    scheduledAt: isScheduled ? new Date(scheduledMs).toISOString() : '',
    isScheduled,
    youtubeVideoId: String(body.youtubeVideoId || '').trim(),
    videoBytes,
    hasVideo: Boolean(videoKey),
    publishYoutube: CONFIG.YOUTUBE && !dryRun && Boolean(videoKey),
    publishInstagram: CONFIG.INSTAGRAM && CONFIG.INSTAGRAM_REELS !== false && !dryRun && Boolean(videoKey),
    publishTiktok: CONFIG.TIKTOK && !dryRun && Boolean(videoKey),
    publishInstagramStory: CONFIG.INSTAGRAM && CONFIG.INSTAGRAM_STORIES && !dryRun && Boolean(videoKey),
    publishFacebook: CONFIG.FACEBOOK && !dryRun && Boolean(videoKey),
    publishFacebookStory: CONFIG.FACEBOOK && CONFIG.FACEBOOK_STORIES !== false && !dryRun && Boolean(videoKey),
    cfg: {
      dryRun,
      appUrl: CONFIG.APP_URL,
      appSecret: CONFIG.WEBHOOK_SECRET,
      youtubeCategoryId: CONFIG.YOUTUBE_CATEGORY_ID,
      youtubeRegion: CONFIG.YOUTUBE_REGION,
      instagramUserId: CONFIG.INSTAGRAM_USER_ID,
      instagramToken: CONFIG.INSTAGRAM_TOKEN,
      graphVersion: CONFIG.GRAPH_VERSION,
      facebookPageId: CONFIG.FACEBOOK_PAGE_ID,
      facebookToken,
      tiktokClientKey: CONFIG.TIKTOK_CLIENT_KEY,
      tiktokClientSecret: CONFIG.TIKTOK_CLIENT_SECRET,
      tiktokRefreshToken: CONFIG.TIKTOK_REFRESH_TOKEN,
      tiktokMode: CONFIG.TIKTOK_MODE,
      tiktokPrivacy: CONFIG.TIKTOK_PRIVACY,
      telegramToken: CONFIG.TELEGRAM_BOT_TOKEN,
      telegramChatId: CONFIG.TELEGRAM_CHAT_ID,
    },
  },
  binary,
}];

// Modo prueba / DRY_RUN: no publica, solo muestra lo que haría.
const j = $input.first().json;
return [{ json: { dryRun: true, event: j.event, hasVideo: j.hasVideo, videoMB: +(j.videoBytes / 1048576).toFixed(1),
  youtube: { title: j.ytTitle, privacy: j.privacyStatus }, instagramCaption: j.caption.slice(0, 200), scheduledAt: j.scheduledAt || 'ahora' } }];

const up = $('YouTube: subir Short').first().json;
const r = $input.first().json;
const id = r.id || up.uploadId || up.id;
const __out = { platform: 'youtube', ok: true, videoId: id, url: id ? `https://youtube.com/shorts/${id}` : '', madeForKids: r.status?.selfDeclaredMadeForKids ?? false, privacy: r.status?.privacyStatus };
// Avisar a la app para medir el rendimiento y aprender. Nunca bloquea la publicación.
const __p = $('Validar y preparar').first().json;
for (const __url of [__p.cfg.appUrl, 'http://host.docker.internal:3000'].filter(Boolean)) {
  try {
    await this.helpers.httpRequest({ method: 'POST', url: `${__url}/api/n8n/publication-result`, headers: { 'X-Webhook-Secret': __p.cfg.appSecret || '' },
      body: { reelId: __p.reelId, scriptId: __p.scriptId, title: __p.title, platform: __out.platform, externalId: __out.videoId || __out.mediaId, url: __out.url }, json: true, timeout: 15000 });
    __out.appNotified = true; break;
  } catch (e) { __out.appNotified = false; __out.appError = String(e.message || e).slice(0, 200); }
}
return [{ json: __out }];

// Registra el fallo de esta red sin detener las demás.
const e = $input.first().json;
return [{ json: { platform: 'youtube', ok: false, error: e.error?.message || e.error || e.message || JSON.stringify(e).slice(0, 500) } }];

// Llamada HTTP que, si falla, muestra la respuesta de la red (motivo real del error)
const call = async (opts) => {
  const r = await this.helpers.httpRequest({ ...opts, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} en ${opts.url}: ` + (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 600));
  return body;
};

// Crea el contenedor del Reel en modo "resumable": el video se sube como archivo
// (no hace falta que tu PC tenga una URL pública).
const p = $input.first();
const c = p.json.cfg;
if (!c.instagramUserId || !c.instagramToken) throw new Error('Configura INSTAGRAM_USER_ID e INSTAGRAM_TOKEN en "Validar y preparar"');
const res = await call({
  method: 'POST',
  url: `https://graph.facebook.com/${c.graphVersion}/${c.instagramUserId}/media`,
  qs: {
    media_type: 'REELS',
    upload_type: 'resumable',
    caption: p.json.caption,
    share_to_feed: 'true',
    access_token: c.instagramToken,
  },
  json: true,
});
if (!res || !res.id || !res.uri) throw new Error('Instagram no devolvió el contenedor: ' + JSON.stringify(res));
return [{ json: { ...p.json, igContainerId: res.id, igUploadUri: res.uri }, binary: p.binary }];

// Llamada HTTP que, si falla, muestra la respuesta de la red (motivo real del error)
const call = async (opts) => {
  const r = await this.helpers.httpRequest({ ...opts, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} en ${opts.url}: ` + (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 600));
  return body;
};

// Espera a que Instagram procese el video y lo publica.
const prev = $('Instagram: crear contenedor').first().json;
const c = prev.cfg;
const base = `https://graph.facebook.com/${c.graphVersion}`;
const sleep = ms => new Promise(r => setTimeout(r, ms));

let status = '';
for (let i = 0; i < 24; i++) {
  const st = await call({
    method: 'GET', url: `${base}/${prev.igContainerId}`,
    qs: { fields: 'status_code,status', access_token: c.instagramToken }, json: true,
  });
  status = st.status_code;
  if (status === 'FINISHED') break;
  if (status === 'ERROR' || status === 'EXPIRED') throw new Error('Instagram rechazó el video: ' + JSON.stringify(st));
  await sleep(10000);
}
if (status !== 'FINISHED') throw new Error('Instagram sigue procesando el video tras 4 min (contenedor ' + prev.igContainerId + ')');

const pub = await call({
  method: 'POST', url: `${base}/${c.instagramUserId}/media_publish`,
  qs: { creation_id: prev.igContainerId, access_token: c.instagramToken }, json: true,
});
let permalink = '';
try {
  const m = await call({ method: 'GET', url: `${base}/${pub.id}`, qs: { fields: 'permalink', access_token: c.instagramToken }, json: true });
  permalink = m.permalink || '';
} catch {}
const __out = { platform: 'instagram', ok: true, mediaId: pub.id, url: permalink };
// Avisar a la app para medir el rendimiento y aprender. Nunca bloquea la publicación.
const __p = $('Validar y preparar').first().json;
for (const __url of [__p.cfg.appUrl, 'http://host.docker.internal:3000'].filter(Boolean)) {
  try {
    await this.helpers.httpRequest({ method: 'POST', url: `${__url}/api/n8n/publication-result`, headers: { 'X-Webhook-Secret': __p.cfg.appSecret || '' },
      body: { reelId: __p.reelId, scriptId: __p.scriptId, title: __p.title, platform: __out.platform, externalId: __out.videoId || __out.mediaId, url: __out.url }, json: true, timeout: 15000 });
    __out.appNotified = true; break;
  } catch (e) { __out.appNotified = false; __out.appError = String(e.message || e).slice(0, 200); }
}
return [{ json: __out }];

// Registra el fallo de esta red sin detener las demás.
const e = $input.first().json;
return [{ json: { platform: 'instagram', ok: false, error: e.error?.message || e.error || e.message || JSON.stringify(e).slice(0, 500) } }];

// Llamada HTTP que, si falla, muestra la respuesta de la red (motivo real del error)
const call = async (opts) => {
  const r = await this.helpers.httpRequest({ ...opts, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} en ${opts.url}: ` + (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 600));
  return body;
};

// Renueva el token de TikTok, consulta la cuenta e inicia la subida del archivo.
const p = $input.first();
const c = p.json.cfg;
const store = $getWorkflowStaticData('global');
const refresh = store.tiktokRefreshToken || c.tiktokRefreshToken;
if (!c.tiktokClientKey || !c.tiktokClientSecret || !refresh) throw new Error('Configura TIKTOK_CLIENT_KEY, TIKTOK_CLIENT_SECRET y TIKTOK_REFRESH_TOKEN en "Validar y preparar"');

const form = o => Object.entries(o).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
let tok = await call({
  method: 'POST', url: 'https://open.tiktokapis.com/v2/oauth/token/',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: form({ client_key: c.tiktokClientKey, client_secret: c.tiktokClientSecret, grant_type: 'refresh_token', refresh_token: refresh }),
});
if (typeof tok === 'string') tok = JSON.parse(tok);
if (!tok.access_token) throw new Error('TikTok no renovó el token: ' + JSON.stringify(tok));
store.tiktokRefreshToken = tok.refresh_token || refresh; // se guarda para la próxima vez

const auth = { Authorization: `Bearer ${tok.access_token}`, 'Content-Type': 'application/json; charset=UTF-8' };
const size = p.json.videoBytes;
if (size > 64 * 1024 * 1024) throw new Error('El video supera 64 MB (límite de subida en un solo bloque)');
const source_info = { source: 'FILE_UPLOAD', video_size: size, chunk_size: size, total_chunk_count: 1 };

let init;
if (c.tiktokMode === 'direct') {
  const info = await call({ method: 'POST', url: 'https://open.tiktokapis.com/v2/post/publish/creator_info/query/', headers: auth, body: {}, json: true });
  const options = info?.data?.privacy_level_options || [];
  const privacy = options.includes(c.tiktokPrivacy) ? c.tiktokPrivacy : (options.includes('SELF_ONLY') ? 'SELF_ONLY' : options[0]);
  init = await call({
    method: 'POST', url: 'https://open.tiktokapis.com/v2/post/publish/video/init/', headers: auth, json: true,
    body: { post_info: { title: p.json.caption, privacy_level: privacy, disable_duet: false, disable_comment: false, disable_stitch: false, video_cover_timestamp_ms: 1000 }, source_info },
  });
} else {
  init = await call({
    method: 'POST', url: 'https://open.tiktokapis.com/v2/post/publish/inbox/video/init/', headers: auth, json: true,
    body: { source_info },
  });
}
const d = init?.data || {};
if (!d.upload_url || !d.publish_id) throw new Error('TikTok no inició la subida: ' + JSON.stringify(init));
return [{
  json: { ...p.json, ttAccessToken: tok.access_token, ttPublishId: d.publish_id, ttUploadUrl: d.upload_url, ttContentRange: `bytes 0-${size - 1}/${size}` },
  binary: p.binary,
}];

// Llamada HTTP que, si falla, muestra la respuesta de la red (motivo real del error)
const call = async (opts) => {
  const r = await this.helpers.httpRequest({ ...opts, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} en ${opts.url}: ` + (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 600));
  return body;
};

// Consulta el estado hasta que TikTok termine de procesar.
const prev = $('TikTok: iniciar subida').first().json;
const sleep = ms => new Promise(r => setTimeout(r, ms));
let st = {};
for (let i = 0; i < 20; i++) {
  await sleep(8000);
  st = await call({
    method: 'POST', url: 'https://open.tiktokapis.com/v2/post/publish/status/fetch/',
    headers: { Authorization: `Bearer ${prev.ttAccessToken}`, 'Content-Type': 'application/json; charset=UTF-8' },
    body: { publish_id: prev.ttPublishId }, json: true,
  });
  const s = st?.data?.status;
  if (s === 'PUBLISH_COMPLETE' || s === 'SEND_TO_USER_INBOX') {
    return [{ json: { platform: 'tiktok', ok: true, status: s, publishId: prev.ttPublishId,
      note: s === 'SEND_TO_USER_INBOX' ? 'El video está en tus borradores/notificaciones de TikTok: ábrelo en la app para publicarlo.' : 'Publicado' } }];
  }
  if (s === 'FAILED') throw new Error('TikTok rechazó el video: ' + JSON.stringify(st.data));
}
return [{ json: { platform: 'tiktok', ok: true, status: st?.data?.status || 'PROCESSING', publishId: prev.ttPublishId, note: 'TikTok sigue procesando; revisa la app en unos minutos.' } }];

// Registra el fallo de esta red sin detener las demás.
const e = $input.first().json;
return [{ json: { platform: 'tiktok', ok: false, error: e.error?.message || e.error || e.message || JSON.stringify(e).slice(0, 500) } }];

// Envía a tu Telegram el texto del video para pegarlo en TikTok (el modo bandeja no acepta texto).
const p = $('Validar y preparar').first().json;
const c = p.cfg;
if (!c.telegramToken) return [{ json: { telegram: 'sin configurar (TELEGRAM_BOT_TOKEN vacío)' } }];
const api = `https://api.telegram.org/bot${c.telegramToken}`;
const store = $getWorkflowStaticData('global');
let chatId = c.telegramChatId || store.telegramChatId;
if (!chatId) {
  const up = await this.helpers.httpRequest({ method: 'GET', url: `${api}/getUpdates`, json: true });
  const last = (up.result || []).slice().reverse().find(u => u.message && u.message.chat && u.message.chat.id);
  if (!last) throw new Error('Abre tu bot en Telegram y pulsa "Iniciar" (/start) para que n8n conozca tu chat.');
  chatId = last.message.chat.id;
  store.telegramChatId = chatId;
}
const send = text => this.helpers.httpRequest({ method: 'POST', url: `${api}/sendMessage`, body: { chat_id: chatId, text, disable_web_page_preview: true }, json: true });
if (p.isTest || p.cfg.dryRun) {
  await send('✅ Conexión lista. Aquí te llegará el texto de cada video para publicarlo en TikTok.');
  return [{ json: { telegram: 'prueba enviada', chatId } }];
}
await send('🎬 TikTok: "' + p.title + '" ya está en tu bandeja.\nAbre la notificación en TikTok, copia el siguiente mensaje (mantén presionado → Copiar), pégalo como descripción y publica.');
await send(p.caption.slice(0, 2200));
return [{ json: { telegram: 'enviado', chatId } }];

// Envía a tu Telegram el texto del video para pegarlo en TikTok (el modo bandeja no acepta texto).
const p = $('Validar y preparar').first().json;
const c = p.cfg;
if (!c.telegramToken) return [{ json: { telegram: 'sin configurar (TELEGRAM_BOT_TOKEN vacío)' } }];
const api = `https://api.telegram.org/bot${c.telegramToken}`;
const store = $getWorkflowStaticData('global');
let chatId = c.telegramChatId || store.telegramChatId;
if (!chatId) {
  const up = await this.helpers.httpRequest({ method: 'GET', url: `${api}/getUpdates`, json: true });
  const last = (up.result || []).slice().reverse().find(u => u.message && u.message.chat && u.message.chat.id);
  if (!last) throw new Error('Abre tu bot en Telegram y pulsa "Iniciar" (/start) para que n8n conozca tu chat.');
  chatId = last.message.chat.id;
  store.telegramChatId = chatId;
}
const send = text => this.helpers.httpRequest({ method: 'POST', url: `${api}/sendMessage`, body: { chat_id: chatId, text, disable_web_page_preview: true }, json: true });
if (p.isTest || p.cfg.dryRun) {
  await send('✅ Conexión lista. Aquí te llegará el texto de cada video para publicarlo en TikTok.');
  return [{ json: { telegram: 'prueba enviada', chatId } }];
}
await send('🎬 TikTok: "' + p.title + '" ya está en tu bandeja.\nAbre la notificación en TikTok, copia el siguiente mensaje (mantén presionado → Copiar), pégalo como descripción y publica.');
await send(p.caption.slice(0, 2200));
return [{ json: { telegram: 'enviado', chatId } }];

// Llamada HTTP que, si falla, muestra la respuesta de la red (motivo real del error)
const call = async (opts) => {
  const r = await this.helpers.httpRequest({ ...opts, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} en ${opts.url}: ` + (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 600));
  return body;
};
const sleep = ms => new Promise(r => setTimeout(r, ms));

// Historia de Instagram: contenedor "resumable" (el video se sube como archivo).
const p = $input.first();
const c = p.json.cfg;
if (!c.instagramUserId || !c.instagramToken) throw new Error('Configura INSTAGRAM_USER_ID e INSTAGRAM_TOKEN en "Validar y preparar"');
const res = await call({
  method: 'POST', url: `https://graph.facebook.com/${c.graphVersion}/${c.instagramUserId}/media`,
  qs: { media_type: 'STORIES', upload_type: 'resumable', access_token: c.instagramToken }, json: true,
});
if (!res || !res.id || !res.uri) throw new Error('Instagram no devolvió el contenedor de la historia: ' + JSON.stringify(res));
return [{ json: { ...p.json, igUploadUri: res.uri, igStoryContainerId: res.id }, binary: p.binary }];

// Llamada HTTP que, si falla, muestra la respuesta de la red (motivo real del error)
const call = async (opts) => {
  const r = await this.helpers.httpRequest({ ...opts, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let body = r.body;
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
  if (r.statusCode >= 400) throw new Error(`HTTP ${r.statusCode} en ${opts.url}: ` + (typeof body === 'string' ? body : JSON.stringify(body)).slice(0, 600));
  return body;
};
const sleep = ms => new Promise(r => setTimeout(r, ms));

// Espera a que Instagram procese la historia y la publica.
const prev = $('Historia IG: crear contenedor').first().json;
const c = prev.cfg;
const base = `https://graph.facebook.com/${c.graphVersion}`;
let status = '';
for (let i = 0; i < 24; i++) {
