// Junta vistas, likes y comentarios de YouTube, Instagram y Facebook y los envía a la app,
// que los usa para aprender qué temas, ganchos y títulos funcionan.
const p = $('Validar y preparar').first().json;
const c = p.cfg;
const base = `https://graph.facebook.com/${c.graphVersion}`;
const get = async (url, qs) => {
  const r = await this.helpers.httpRequest({ method: 'GET', url, qs: { ...qs, access_token: c.instagramToken }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  if (r.statusCode >= 400) throw new Error('HTTP ' + r.statusCode + ': ' + JSON.stringify(r.body).slice(0, 300));
  return r.body;
};
const getFb = async (url, qs) => {
  const r = await this.helpers.httpRequest({ method: 'GET', url, qs: { ...qs, access_token: c.facebookToken || c.instagramToken }, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000 });
  if (r.statusCode >= 400) throw new Error('HTTP ' + r.statusCode + ': ' + JSON.stringify(r.body).slice(0, 300));
  return r.body;
};
const items = [], errors = [];

// YouTube (viene de los nodos anteriores)
const yt = $input.first().json;
if (yt.error) errors.push('YouTube: ' + JSON.stringify(yt.error).slice(0, 300));
for (const v of yt.items || []) {
  const s = v.statistics || {};
  items.push({ platform: 'youtube', externalId: v.id, url: 'https://youtube.com/shorts/' + v.id, title: v.snippet?.title, publishedAt: v.snippet?.publishedAt,
    views: Number(s.viewCount || 0), likes: s.likeCount != null ? Number(s.likeCount) : null, comments: s.commentCount != null ? Number(s.commentCount) : null });
}

// Instagram (Reels)
if (c.instagramUserId && c.instagramToken) {
  try {
    const media = await get(base + '/' + c.instagramUserId + '/media', { fields: 'id,caption,permalink,timestamp,media_type,media_product_type,like_count,comments_count', limit: 50 });
    for (const m of media.data || []) {
      if (m.media_type !== 'VIDEO') continue;
      const it = { platform: 'instagram', externalId: m.id, url: m.permalink, title: (m.caption || '').split('\n')[0], publishedAt: m.timestamp,
        likes: m.like_count ?? null, comments: m.comments_count ?? null, extra: { product: m.media_product_type } };
      try {
        const ins = await get(base + '/' + m.id + '/insights', { metric: 'views,reach,saved,shares' });
        for (const d of ins.data || []) {
          const val = d.values?.[0]?.value ?? d.total_value?.value;
          if (d.name === 'views') it.views = val; else if (d.name === 'saved') it.saves = val;
          else if (d.name === 'shares') it.shares = val; else if (d.name === 'reach') it.extra.reach = val;
        }
      } catch (e) { it.extra.insightsError = String(e.message).slice(0, 200); }
      items.push(it);
    }
  } catch (e) { errors.push('Instagram: ' + e.message); }
}

// Facebook (Reels de la página)
if (c.facebookPageId && (c.facebookToken || c.instagramToken)) {
  try {
    const reels = await getFb(base + '/' + c.facebookPageId + '/video_reels', { fields: 'id,description,permalink_url,created_time', limit: 50 });
    for (const r of reels.data || []) {
      const link = r.permalink_url ? (r.permalink_url.startsWith('http') ? r.permalink_url : 'https://www.facebook.com' + r.permalink_url) : 'https://www.facebook.com/reel/' + r.id;
      const it = { platform: 'facebook', externalId: r.id, url: link, title: (r.description || '').split('\n')[0], publishedAt: r.created_time, extra: {} };
      try {
        // Cada métrica por separado: si una no existe en esta versión de la API, las demás igual llegan
        const bad = [];
        for (const metric of ['blue_reels_play_count', 'fb_reels_total_plays', 'post_impressions_unique', 'post_video_likes_by_reaction_type', 'post_video_social_actions']) {
          try {
            const ins = await getFb(base + '/' + r.id + '/video_insights', { metric });
            for (const d of ins.data || []) {
              const val = d.values?.[0]?.value;
              if (d.name === 'blue_reels_play_count' || d.name === 'fb_reels_total_plays') it.views = Math.max(it.views || 0, Number(val) || 0);
              else if (d.name === 'post_impressions_unique') it.extra.reach = val;
              else if (d.name === 'post_video_likes_by_reaction_type') it.likes = Object.values(val || {}).reduce((a, b) => a + (Number(b) || 0), 0);
              else if (d.name === 'post_video_social_actions') { it.comments = val?.COMMENT ?? null; it.shares = val?.SHARE ?? null; }
            }
          } catch (e) { bad.push(metric + ': ' + String(e.message).slice(0, 120)); }
        }
        if (bad.length) it.extra.insightsSkipped = bad;
        if (it.views == null && bad.length) throw new Error(bad[0]);
      } catch (e) { it.extra.insightsError = String(e.message).slice(0, 200); }
      items.push(it);
    }
  } catch (e) { errors.push('Facebook: ' + e.message); }
}

// Enviar a la app
let app = null;
if (items.length) {
  for (const url of [c.appUrl, 'http://host.docker.internal:3000'].filter(Boolean)) {
    try {
      app = await this.helpers.httpRequest({ method: 'POST', url: url + '/api/n8n/metrics', headers: { 'X-Webhook-Secret': c.appSecret || '' }, body: { items }, json: true, timeout: 30000 });
      break;
    } catch (e) { errors.push('App (' + url + '): ' + String(e.message).slice(0, 200)); }
  }
}
// Errores de estadísticas por red (uno de cada tipo) para diagnosticar permisos
for (const i of items) if (i.extra?.insightsError) { const m = i.platform + ' insights: ' + i.extra.insightsError.replace(/,?\\?"fbtrace_id.*$/, ''); if (!errors.includes(m)) errors.push(m); }
const byPlatform = items.reduce((a, i) => (a[i.platform] = (a[i.platform] || 0) + 1, a), {});
return [{ json: { collected: items.length, byPlatform, app, errors } }];

